class Solution {
public:
    int maxFrequency(vector<int>& nums, int k, int numOperations) {
        sort(nums.begin(), nums.end());
        int n = (int)nums.size();
        int ans = 0;
        set<int> cand;
        for (int i = 0; i < n; i++) {
            cand.insert(nums[i]);
            cand.insert(nums[i] - k);
            cand.insert(nums[i] + k);
        }
        for (int v : cand) {
            int inRange = (int)(upper_bound(nums.begin(), nums.end(), v + k)
                              - lower_bound(nums.begin(), nums.end(), v - k));
            int already = (int)(upper_bound(nums.begin(), nums.end(), v)
                              - lower_bound(nums.begin(), nums.end(), v));
            int res = already + min(numOperations, inRange - already);
            ans = max(ans, res);
        }
        return ans;
    }
};
